WITH cleaned AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CONCAT_WS(',', email, level) AS email_level_key, COALESCE(job_title, 'NONE') AS job_title_clean FROM employees WHERE level IS NOT NULL) SELECT CASE WHEN salary >= 141000 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_tier, DATE_TRUNC('WEEK', hire_date) AS week_start, ROUND(AVG(salary), 2) AS avg_salary, COUNT(CASE WHEN level = 'L3' THEN 1 END) AS l3_count, APPROX_PERCENTILE(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, RANK() OVER (PARTITION BY CASE WHEN salary >= 141000 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(CASE WHEN level = 'L3' THEN 1 END) DESC) AS l3_count_rank FROM cleaned GROUP BY salary_tier, week_start HAVING COUNT(CASE WHEN level = 'L3' THEN 1 END) >= 1;
